// Normalise and check facts
// Works for both entry points (form or sheet) and runs the rule-based material information checks
// before any AI is involved, so missing Part A facts are caught even if the AI misses them.
//
// Google Sheet tab "Listings" needs these column headers (row 1):
// listing_id, status, negotiator_email, address, property_type, bedrooms, bathrooms, receptions, floor_area_sqm, price, price_qualifier, tenure, lease_years_remaining, ground_rent, service_charge, council_tax_band, epc_rating, heating, utilities, broadband, mobile_signal, parking, other_material_info, key_facts, known_issues, headline, summary, description, key_features, flagged_claims, material_info_gaps, risk_level, confidence, review_reasons, checked_at, error_message
//
// Based on the National Trading Standards (NTSELAT) material information guidance for England, Wales
// and Northern Ireland: Part A (price, council tax, tenure and leasehold costs), Part B (physical
// characteristics, utilities, broadband, mobile, parking) and Part C (flood risk, building safety,
// restrictions and rights, planning, accessibility, mining). Scotland uses Home Reports: adjust the rules.
const LABELS = {"Your email": "negotiator_email", "Listing ID (optional)": "listing_id", "Property address": "address", "Property type": "property_type", "Bedrooms": "bedrooms", "Bathrooms": "bathrooms", "Reception rooms": "receptions", "Floor area (sq m)": "floor_area_sqm", "Price qualifier": "price_qualifier", "Price (GBP)": "price", "Tenure": "tenure", "Lease years remaining": "lease_years_remaining", "Ground rent (GBP per year)": "ground_rent", "Service charge (GBP per year)": "service_charge", "Council tax band": "council_tax_band", "EPC rating": "epc_rating", "Heating": "heating", "Utilities (electricity, water, sewerage)": "utilities", "Broadband": "broadband", "Mobile signal": "mobile_signal", "Parking": "parking", "Other material information": "other_material_info", "Key facts and features": "key_facts", "Known issues to disclose": "known_issues"};
const s = (v) => (v === undefined || v === null ? '' : String(v).trim());
const blank = (v) => !s(v) || /^(n\/?a|tbc|unknown|-|not yet known)$/i.test(s(v));

return $input.all().map((item) => {
  const src = item.json;
  const fromForm = Object.keys(src).some((k) => k in LABELS);
  const row = {};
  for (const [k, v] of Object.entries(src)) {
    const col = LABELS[k] || k;
    row[col] = Array.isArray(v) ? v.join(', ') : s(v);
  }
  if (!row.listing_id) {
    const stamp = new Date().toISOString().replace(/\D/g, '').slice(2, 12);
    row.listing_id = 'LST-' + stamp + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();
  }

  // Part A (and EPC): these block the listing until they are filled in.
  const partA = [];
  const poa = /application|poa/i.test(row.price_qualifier);
  if (blank(row.price) || poa) partA.push('Price (Part A): a price must be shown, not POA or blank');
  if (blank(row.council_tax_band)) partA.push('Council tax band or domestic rates (Part A)');
  if (blank(row.tenure)) partA.push('Tenure (Part A)');
  if (/lease|share/i.test(row.tenure)) {
    if (blank(row.lease_years_remaining)) partA.push('Lease years remaining (Part A, leasehold)');
    if (blank(row.ground_rent)) partA.push('Ground rent (Part A, leasehold)');
    if (blank(row.service_charge)) partA.push('Service charge (Part A, leasehold)');
  }
  if (blank(row.epc_rating)) partA.push('EPC rating: must be available or ordered before marketing');

  // Part B and C: noted for the negotiator; they only block if STRICT_MATERIAL_INFO is true in Settings.
  const other = [];
  const partB = { property_type: 'Property type', bedrooms: 'Number of bedrooms', bathrooms: 'Number of bathrooms',
    heating: 'Heating', utilities: 'Electricity, water and sewerage', broadband: 'Broadband', mobile_signal: 'Mobile signal', parking: 'Parking' };
  for (const [col, label] of Object.entries(partB)) if (blank(row[col])) other.push(label + ' (Part B)');
  if (blank(row.other_material_info)) other.push('Part C: nothing recorded on flood risk, building safety, restrictions and rights, planning, accessibility or mining');

  const facts = [
    ['Address', row.address], ['Property type', row.property_type], ['Bedrooms', row.bedrooms], ['Bathrooms', row.bathrooms],
    ['Reception rooms', row.receptions], ['Floor area (sq m)', row.floor_area_sqm],
    ['Price', [row.price_qualifier, row.price ? 'GBP ' + row.price : ''].filter(Boolean).join(' ')],
    ['Tenure', row.tenure], ['Lease years remaining', row.lease_years_remaining], ['Ground rent', row.ground_rent],
    ['Service charge', row.service_charge], ['Council tax band', row.council_tax_band], ['EPC rating', row.epc_rating],
    ['Heating', row.heating], ['Utilities', row.utilities], ['Broadband', row.broadband], ['Mobile signal', row.mobile_signal],
    ['Parking', row.parking], ['Other material information', row.other_material_info],
    ['Key facts', row.key_facts], ['Known issues to disclose', row.known_issues],
  ].filter(([, v]) => !blank(v)).map(([k, v]) => k + ': ' + v).join('\n');

  return { json: { ...row, _source: fromForm ? 'form' : 'sheet', _part_a_missing: partA, _other_gaps: other, _facts_text: facts } };
});

// The AI step failed for this listing (after the model's own retries). Keep the facts and the reason,
// so the listing is logged as "error" and the rest of the batch carries on.
const e = $json.error;
const msg = typeof e === 'string' ? e : (e && (e.message || e.description)) || 'AI step failed';
return { json: { ...$('Loop over listings').item.json, ai_output: null, ai_error: String(msg) } };

// Score and route
// Combines the AI review with rule-based checks and sets the status:
// needs_facts (Part A missing) > needs_review (risky claims, low confidence, known issues) > ready_to_publish.
// Each item carries the listing facts, your Settings and the AI result (attached inside the loop),
// so nothing here depends on n8n item pairing.
const s = $json;
const out = s.ai_output || {};
const txt0 = (v) => (v === undefined || v === null ? '' : String(v).trim());
if (txt0(s.ai_error)) {
  const row = {};
  for (const col of ["listing_id", "negotiator_email", "address", "property_type", "bedrooms", "bathrooms", "receptions", "floor_area_sqm", "price", "price_qualifier", "tenure", "lease_years_remaining", "ground_rent", "service_charge", "council_tax_band", "epc_rating", "heating", "utilities", "broadband", "mobile_signal", "parking", "other_material_info", "key_facts", "known_issues"]) row[col] = txt0(s[col]);
  // Copy columns are left out so an earlier draft in the sheet is not wiped.
  return { json: { ...row, status: 'error', error_message: txt0(s.ai_error).slice(0, 500),
    checked_at: new Date().toISOString().replace('T', ' ').slice(0, 16) + ' UTC',
    notify_to: txt0(s.negotiator_email) || txt0(s.FALLBACK_NOTIFY_EMAIL) } };
}
const txt = (v) => (v === undefined || v === null ? '' : String(v).trim());
const list = (a) => (Array.isArray(a) ? a : []).map(txt).filter(Boolean);
const facts = (s._facts_text || '').toLowerCase();
const features = list(out.key_features);
const copy = [out.headline, out.summary, out.description, ...features].map(txt).join('\n');

// 1. Claims from the AI review
const claims = (Array.isArray(out.claims) ? out.claims : []).map((c) => ({
  claim: txt(c.claim), category: txt(c.category) || 'other',
  risk: ['low', 'medium', 'high'].includes(c.risk) ? c.risk : 'medium',
  reason: txt(c.reason), suggested_fix: txt(c.suggested_fix), by: 'AI review',
})).filter((c) => c.claim);

// 2. Rule-based phrase checks: flag risky wording in the copy that does not appear in your facts.
const RULES = [
  [/\b(best|finest|unrivalled|unbeatable|perfect|most sought[- ]after|second to none)\b/i, 'superlative', 'medium', 'Superlative not backed by your facts'],
  [/\b\d+\s*(min|mins|minutes?)\b|\bwalking distance\b|\bstone'?s throw\b/i, 'distance_or_time', 'medium', 'Distance or travel time: verify the route and time'],
  [/\b(outstanding|ofsted|catchment)\b/i, 'schools', 'high', 'School or catchment claim: catchments change and must be verified'],
  [/\b(yield|rental income|investment opportunity|return on investment)\b/i, 'investment_or_yield', 'high', 'Investment or yield claim needs evidence'],
  [/\b(planning (permission|potential)|potential to extend|scope to extend|subject to planning|stpp?)\b/i, 'planning_or_legal', 'high', 'Planning claim: check permissions or remove'],
  [/\b(no (onward )?chain|chain[- ]free|vacant possession)\b/i, 'chain_or_availability', 'medium', 'Chain status: confirm with the seller'],
  [/\b(newly|recently) (renovated|refurbished|fitted|rewired|replaced)\b|\bnew (roof|boiler|windows)\b/i, 'condition_or_works', 'medium', 'Works claim: ask for dates and certificates'],
  [/\b(sq ?ft|square f(ee|oo)t|sq ?m|m²)\b/i, 'size_or_measurement', 'medium', 'Measurement: check it matches the EPC or floor plan'],
];
for (const [re, category, risk, reason] of RULES) {
  const m = copy.match(re);
  const seen = (w) => claims.some((c) => c.claim.toLowerCase().includes(w));
  if (m && !facts.includes(m[0].toLowerCase()) && !seen(m[0].toLowerCase())) {
    claims.push({ claim: m[0], category, risk, reason: reason + ' (wording added by the AI, not in your facts)', suggested_fix: 'Remove it or add the evidence to your facts', by: 'Rules' });
  }
}

// 3. Material information gaps: rules first, then anything else the AI spotted.
const partA = s._part_a_missing || [];
const ruleGaps = [...partA, ...(s._other_gaps || [])];
const aiGaps = list(out.missing_material_info).filter((g) => !ruleGaps.some((r) => r.toLowerCase().includes(g.toLowerCase())));
const gaps = [...ruleGaps, ...aiGaps.map((g) => g + ' (AI)')];

// 4. Decide
let confidence = Number(out.confidence);
if (!Number.isFinite(confidence)) confidence = 0;
confidence = Math.max(0, Math.min(1, confidence));
const th = Number(s.CONFIDENCE_THRESHOLD);
const threshold = Number.isFinite(th) && th >= 0 && th <= 1 ? th : 0.8;
const rank = { none: 0, low: 1, medium: 2, high: 3 };
const risk = claims.reduce((r, c) => (rank[c.risk] > rank[r] ? c.risk : r), 'none');
const reasons = [];
if (partA.length) reasons.push('Missing required facts: ' + partA.join('; '));
if (s.STRICT_MATERIAL_INFO === true && (s._other_gaps || []).length) reasons.push('Strict mode: Part B/C information missing');
if (rank[risk] >= 2) reasons.push(claims.filter((c) => rank[c.risk] >= 2).length + ' medium or high risk claim(s)');
if (confidence < threshold) reasons.push('AI confidence ' + confidence.toFixed(2) + ' is below ' + threshold);
if (txt(s.known_issues)) reasons.push('Known issues listed: check they are disclosed clearly');
if (!txt(out.headline) || !txt(out.description)) reasons.push('AI returned incomplete copy');

const status = partA.length || (s.STRICT_MATERIAL_INFO === true && (s._other_gaps || []).length) ? 'needs_facts'
  : reasons.length ? 'needs_review' : 'ready_to_publish';

const bullet = (a) => a.map((x) => '- ' + x).join('\n');
const row = {};
for (const col of ["listing_id", "negotiator_email", "address", "property_type", "bedrooms", "bathrooms", "receptions", "floor_area_sqm", "price", "price_qualifier", "tenure", "lease_years_remaining", "ground_rent", "service_charge", "council_tax_band", "epc_rating", "heating", "utilities", "broadband", "mobile_signal", "parking", "other_material_info", "key_facts", "known_issues"]) row[col] = txt(s[col]);
return { json: {
  ...row,
  status,
  headline: txt(out.headline),
  summary: txt(out.summary),
  description: txt(out.description),
  key_features: bullet(features),
  flagged_claims: claims.length ? claims.map((c) => '- [' + c.risk.toUpperCase() + '] "' + c.claim + '": ' + c.reason + '. Try: ' + c.suggested_fix + ' (' + c.by + ')').join('\n') : 'None flagged',
  material_info_gaps: gaps.length ? bullet(gaps) : 'None found',
  risk_level: risk,
  confidence: Math.round(confidence * 100) / 100,
  review_reasons: reasons.join('\n'),
  checked_at: new Date().toISOString().replace('T', ' ').slice(0, 16) + ' UTC',
  error_message: '',
  // Not written to the sheet (ignored as extra fields), used by the notification step:
  notify_to: txt(s.negotiator_email) || txt(s.FALLBACK_NOTIFY_EMAIL),
  blocking_gaps: partA.length ? bullet(partA) : '',
  other_gaps: bullet([...(s._other_gaps || []), ...aiGaps.map((g) => g + ' (AI)')]),
} };

